def look_and_say_sequence(start, n):
    def describe(s):
        result = []
        i = 0
        while i < len(s):
            count = 1
            while i + 1 < len(s) and s[i] == s[i + 1]:
                i += 1
                count += 1
            result.append(str(count) + s[i])
            i += 1
        return ''.join(result)

    current = start
    for _ in range(n - 1):
        current = describe(current)
    return current
